import {MatchingServiceClient,assertContract} from './service-client.js';
const app=document.querySelector('#app'),client=new MatchingServiceClient();let options,matchResponse,compareResponse,state={step:0,mode:'broad_exploration',schoolState:'',online:false,maxPrice:'',affordability:0,career:0,selected:new Set()};
const money=v=>v==null?'Evidence unavailable':`$${Number(v).toLocaleString()}`,first=(a)=>Array.isArray(a)&&a.length?a[0]:null;
function steps(){document.querySelectorAll('#steps li').forEach((x,i)=>x.classList.toggle('active',i===state.step))}function next(){state.step++;render()}function back(){state.step--;render()}
function request(){let constraints=[];if(state.schoolState)constraints.push({constraint_id:'school_states',field:'state',operator:'in',value:[state.schoolState],unknown_policy:'keep_visible'});if(state.online)constraints.push({constraint_id:'online_requirement',field:'online_available',operator:'eq',value:true,unknown_policy:'keep_visible'});if(state.maxPrice)constraints.push({constraint_id:'net_price_ceiling',field:'finance__net_price',operator:'lte',value:+state.maxPrice,unknown_policy:'keep_visible'});let preferences=[];if(state.affordability)preferences.push({preference_id:'affordability_priority',dimension:'affordability',importance:state.affordability,priority_explicit:true});if(state.career)preferences.push({preference_id:'career_pathway_priority',dimension:'career_pathway_fit',importance:state.career,priority_explicit:true});return {schema_version:'1.0',decision_mode:state.mode,constraints,preferences,career_preferences:[],geography:{school_location_semantics:state.schoolState?'selected_places':'no_preference',selected_states:state.schoolState?[state.schoolState]:[],work_market_semantics:'unspecified',intended_work_market:null},page:1,page_size:20,data_version:options.data_version}}
function start(){app.innerHTML=`<div class="panel"><h2>What are you trying to decide?</h2><label>Starting point</label><select id="mode"><option value="broad_exploration">Explore colleges, programs, and careers together</option><option value="career_first">Start with careers that may fit me</option><option value="college_program_first">Find colleges for a program I have in mind</option><option value="compare_known">Compare programs I already know</option><option value="transfer">Plan a transfer</option><option value="returning_student">Return to college or finish a degree</option></select><button id="next">Continue</button></div>`;mode.value=state.mode;mode.onchange=e=>state.mode=e.target.value;document.querySelector('#next').onclick=next}
function must(){let states=options.options.states||[];app.innerHTML=`<div class="panel"><h2>Your must-haves</h2><p class="note">Choices come from the active service options contract. Unknown evidence stays visible.</p><label>School state</label><select id="st"><option value="">No requirement</option>${states.map(x=>`<option value="${x.value}">${x.label}</option>`).join('')}</select><label><input id="on" type="checkbox" style="width:auto"> Must be available online</label><label>Maximum annual net price</label><input id="price" type="number" min="0" placeholder="No firm ceiling"><p class="note">Net price is not tuition or total cost of attendance.</p><button id="prev" class="secondary">Back</button><button id="go">Continue</button></div>`;st.value=state.schoolState;on.checked=state.online;price.value=state.maxPrice;prev.onclick=back;go.onclick=()=>{state.schoolState=st.value;state.online=on.checked;state.maxPrice=price.value;next()}}
function priorities(){app.innerHTML=`<div class="panel"><h2>What matters most?</h2><p>Skip anything that is not important. No default weights are assigned.</p><label>Keeping costs low: <span id="av">${state.affordability||'skip'}</span></label><input id="a" type="range" min="0" max="5" value="${state.affordability}"><label>Career pathways: <span id="cv">${state.career||'skip'}</span></label><input id="c" type="range" min="0" max="5" value="${state.career}"><button id="prev" class="secondary">Back</button><button id="go">Find matches</button></div>`;a.oninput=()=>av.textContent=a.value==0?'skip':a.value;c.oninput=()=>cv.textContent=c.value==0?'skip':c.value;prev.onclick=back;go.onclick=async()=>{state.affordability=+a.value;state.career=+c.value;app.innerHTML='<p>Loading governed match response…</p>';matchResponse=assertContract(await client.match(request()),'match');next()}}
function matches(){let rows=matchResponse.results;app.innerHTML=`<h2>Matched programs</h2><p>${matchResponse.result_count} candidates in this contract response. No universal rank is inferred by the browser.</p><div class="grid">${rows.map(c=>{let cur=first(c.labor_market?.selected_work_market?.soc_evidence),out=first(c.labor_market?.long_term_outlook?.soc_evidence);return `<article class="card"><h3>${c.program.name}</h3><p>${c.institution.name} · ${c.institution.state||''}</p><div class="metric"><strong>Career pathways</strong><br>${(c.career_pathways?.soc_codes||[]).map(x=>`<span class="tag">${x}</span>`).join('')||'Evidence unavailable'}</div><div class="metric"><strong>Current-market median wage</strong><br>${money(cur?.median_wage)}</div><div class="metric"><strong>Long-term outlook</strong><br>${out?`${out.employment_change_pct}% through ${out.projection_year}`:'Evidence unavailable'}</div><div class="metric"><strong>Evidence coverage</strong><br>${c.evidence_coverage?.overall_status||'Unknown'}</div><label><input class="pick" data-id="${c.candidate_id}" type="checkbox" style="width:auto" ${state.selected.has(c.candidate_id)?'checked':''}> Compare this program</label></article>`}).join('')}</div><button id="prev" class="secondary">Change priorities</button><button id="cmp">Compare selected</button>`;document.querySelectorAll('.pick').forEach(x=>x.onchange=()=>x.checked?state.selected.add(x.dataset.id):state.selected.delete(x.dataset.id));prev.onclick=back;cmp.onclick=async()=>{if(state.selected.size<2)return alert('Select at least two programs to compare.');app.innerHTML='<p>Loading comparison…</p>';compareResponse=assertContract(await client.compare([...state.selected]),'compare');next()}}
function compare(){let cs=compareResponse.candidates;app.innerHTML=`<h2>Compare programs</h2><p class="note">No automatic winner. Missing evidence is not zero. The browser displays service evidence rather than recalculating it.</p><div class="compare"><table><thead><tr><th>Evidence</th>${cs.map(c=>`<th>${c.program.name}<br><small>${c.institution.name}</small></th>`).join('')}</tr></thead><tbody><tr><th>Net price</th>${cs.map(c=>`<td>${money(c.affordability?.net_price?.value)}</td>`).join('')}</tr><tr><th>Program earnings</th>${cs.map(c=>`<td>${money(c.program_outcomes?.median_earnings?.value)}</td>`).join('')}</tr></tbody></table></div><button id="prev" class="secondary">Back to matches</button><button id="restart">Change my answers</button>`;prev.onclick=back;restart.onclick=()=>{state.step=1;render()}}
function render(){steps();[start,must,priorities,matches,compare][state.step]()}
(async()=>{try{await client.load();options=assertContract(await client.options(),'options');render()}catch(e){app.innerHTML=`<div class="panel"><h2>Prototype unavailable</h2><p>${e.message}</p></div>`}})();
